-- Contar títulos na inadimplência (EMITIDO, vencidos, TODOS os tipos)
SELECT 'inadimplencia_all_types' as source, COUNT(*) as cnt FROM accounts_receivable 
WHERE estado = 'EMITIDO' AND vencimento_data <= NOW();

-- Contar títulos na inadimplência (filtro RECEIVABLE_VALID_TYPES)
SELECT 'inadimplencia_valid_types' as source, COUNT(*) as cnt FROM accounts_receivable 
WHERE estado = 'EMITIDO' AND vencimento_data <= NOW() 
AND tipo IN ('TITULO', 'RECEITA', 'ADIANTAMENTO');

-- Contar títulos na planilha de cobrança
SELECT 'planilha' as source, COUNT(*) as cnt FROM cobranca_planilha;

